# Analyze session with powershell instead of python
$session = "C:\Users\anshg\.chakra\projects\C--Users-anshg--cursor-headless-harness-datagen-harness-chakra\3e1d34dd-9589-4f6a-89f2-85f52b50574c.jsonl"
$confirmCount=0; $textOnly=0; $withTools=0; $maxOut=0
Get-Content $session | ForEach-Object {
  if ($_ -match '"role":"assistant"') {
    if ($_ -match '"type":"tool_use"') { $withTools++ } else { $textOnly++ }
    if ($_ -match 'Please confirm|If you.?d like|give the go-ahead|Once you give|want me to') { $confirmCount++ }
    if ($_ -match 'max_output_tokens|max_tokens') { $maxOut++ }
  }
}
"assistant with tools: $withTools"
"assistant text-only (turn ends): $textOnly"
"confirm-ish phrases: $confirmCount"
"max_tokens mentions: $maxOut"
Write-Host "==== ENV / profile ===="
Get-Content "c:\Users\anshg\.cursor\headless_harness_datagen\harness\chakra\.chakra-profile.json"
Write-Host "==== global settings ===="
Get-Content "C:\Users\anshg\.chakra\settings.json"
Write-Host "==== check CLAUDE.md / AGENTS ===="
@("CLAUDE.md","AGENTS.md",".chakra\CLAUDE.md",".claude\CLAUDE.md") | ForEach-Object {
  $p = Join-Path "c:\Users\anshg\.cursor\headless_harness_datagen\harness\chakra" $_
  if (Test-Path $p) { "EXISTS $p" } else { "missing $_" }
}
Write-Host "==== enabled plugins ===="
if (Test-Path "C:\Users\anshg\.chakra\plugins\installed_plugins.json") { Get-Content "C:\Users\anshg\.chakra\plugins\installed_plugins.json" }
Get-ChildItem "C:\Users\anshg\.chakra\plugins" -ErrorAction SilentlyContinue | Select-Object Name
rg -n "CLAUDE_CODE_MAX_OUTPUT_TOKENS|max_output_tokens|8192" "c:\Users\anshg\.cursor\headless_harness_datagen\harness\chakra\src" -g "*.ts" --max-count 25 2>$null | Select-Object -First 25

# Sample text-only assistant endings from latest session
$session = "C:\Users\anshg\.chakra\projects\C--Users-anshg--cursor-headless-harness-datagen-harness-chakra\3e1d34dd-9589-4f6a-89f2-85f52b50574c.jsonl"
$n=0
Get-Content $session | ForEach-Object {
  if ($_ -match '"role":"assistant"' -and $_ -notmatch '"type":"tool_use"') {
    $n++
    if ($n -le 6 -or $_ -match 'confirm|go-ahead|If you|proceed|scaffold|Phase') {
      # extract a bit of text
      if ($_ -match '"text":"([^"]{40,220})') {
        "STOP#$n : $($Matches[1].Substring(0,[Math]::Min(200,$Matches[1].Length)))"
      }
    }
  }
}
"total text-only stops counted: $n"
Write-Host "==== check for recovery / max output in session ===="
Select-String -Path $session -Pattern "max_output_tokens|recovery|Please confirm|continue implementing" | Select-Object -First 15 | ForEach-Object { $_.Line.Substring(0,[Math]::Min(160,$_.Line.Length)) }
Write-Host "==== how chakra loads profile ===="
rg -n "chakra-profile|CLAUDE_CODE_MAX_OUTPUT_TOKENS|OPENAI_MODEL" "c:\Users\anshg\.cursor\headless_harness_datagen\harness\chakra" -g "*.{ts,js,json,md,sh}" --max-count 30 2>$null | Select-Object -First 30
